import React , {useEffect, useState} from "react";

import "./styles.css"
import {  
	parseDateMMDDYYYY, gen16CodeId, updStore,  ObjectKeys, 
} from "../../../stores/Utils";

import { CloseModal } from "../../../components/DialogHRM";
import { SvgIcon_Cmpt } from "../../../components";
import { Invoice2Pdf } from "../services/export_service";



const Svg = SvgIcon_Cmpt();



const ViewInvoice  = ({ data, item }) => {

	const [, set_obs] = useState(0);


	
	useEffect(() => {
		updStore("inv_products_list", null);
		updStore("inv_products_stock",null);

		updObs();
		//get_inventory_by_prod(item.productId,updObs)
	},[item.productId]);

	const updObs =  () => {
		set_obs(gen16CodeId())
	}




	const close =  (element) => {
		CloseModal({id:data.modalID});
		
	}
	


	const printInvoice =  () => {
		let data2print =  {...item};
		Invoice2Pdf(data2print)

		
	}


	let result = item?.tax + item?.sales - (item?.cost) - item?.estimated_monthly_storage_fee;



	return (
		<div style={{
			maxHeight: "98vh",
			minHeight: "92vh",
			width: "960px",
			overflow: "auto",
			background: "var(--hrm_palette-general-background-b)",
			borderRadius: 13,
			padding: "10px 19px 30px"
		}}>
			<div className="_dsplFlx ">
				<p className="title_collect gSansFont">
					{ "ASIN:" } 
				</p>
				<p className="title_collect fntW600 gSansFont" style={{color: "#646cff"}}>
					{ item?.asin} 
				</p>
				<div className="flexSpace"/>
				
				
				<div className="icon_print" onClick={printInvoice}>
					<Svg name={"printer"} color={"var(--hrm_palette-inverse-background-b)"}/>
				</div>
			</div>

			<div className="acc_dtls" style={{marginTop: 10, marginLeft: 2}}>
			
				<div className="_dsplFlx"  >
					<div className="name">
						<div className=" code gSansFont" style={{ color: "var(--hrm_palette-inverse-background-b)", fontSize: 14}} >
							{item?.title} 
						</div>
					</div>
				</div>
			</div>
			
			
			<div className="_dsplFlx " style={{marginBottom: 8}}>
				
				<div className="flexSpace"/>
				<div className="_dsplFlx"  >
					<div className="name gSansFont" style={{color: "var(--hrm_palette-item_coll_gray)"}}>
					{item?.description} 
					</div>
				</div>
			
			</div>

					


			
			
			
			<div className="scollVh subMHeight amzn-hdr" style={{height: "calc(94svh - 130px)"}}>
			
				<div className="_dsplFlx hdr_bar purple">
					<div className="tr_bar_20"  style={{textAlign:"left", paddingLeft: 14}}>
						Warehouse
					</div>
					<div className="tr_bar_15 txt_alg_padd">
						Stock
					</div>
					<div className="tr_bar_15 txt_alg_padd" >
						Vendidos
					</div>
					<div className="tr_bar_15 txt_alg_padd" >
						Transferidos
					</div>
					<div className="tr_bar_15 txt_alg_padd">
						Recibidos
					</div>
					<div className="tr_bar_15 txt_alg_padd" >
						Perdidos
					</div>
					<div className="tr_bar_15 txt_alg_padd" >
						Encontrados
					</div>
				</div>
				{item.locations && ObjectKeys(item.locations)?.map((element) => 
					<ListingWarehouse 
						key={element} 
						element={item.locations[element]} 
						idKey={element} 
						close={close}
					/>
				)}
				<div style={{margin: 30}}></div>
				<div className="_dsplFlx hdr_bar purple ">
					<div className="tr_bar_25"  style={{textAlign:"left", paddingLeft: 14}}>
						Order ID
					</div>
					<div className="tr_bar_10 txt_alg_padd" >
						Fecha
					</div>
					<div className="flexSpace"/>
					<div className="tr_bar_15 txt_alg_padd">
						Status
					</div>
					
					<div className="tr_bar_10 txt_alg_padd" >
						Price
					</div>
					<div className="tr_bar_10 txt_alg_padd">
						Quantity
					</div>
				</div>
				{item.orders && item.orders?.map((element) => 
					<ListingProducts 
						key={element["amazon-order-id"]} 
						element={element} 
						idKey={element["amazon-order-id"]} 
						close={close}
					/>
				)}
			
				<div className="_dsplFlx totalsGrid" style={{margin:"19px 15px 10px"}} >
					<div className="tr_bar_60"/>
					<div className="tr_bar_40 brdTp">
						<div className="_dsplFlx totals"  >
							<div className="code tr_bar_70 gSansFont"  >
								{"Subtotal:"} 
							</div>
							<div className="name tr_bar_30 gSansFont" >
								${item?.sales?.toFixed(2)}
							</div>	
							
						</div>
						<div className="_dsplFlx totals" >
							<div className="code tr_bar_70 gSansFont" >
								{"tax:"} 
							</div>
							<div className="name tr_bar_30 gSansFont" >
								${item?.tax ? item?.tax.toFixed(2):"0.00"} 
							</div>	
						</div>
						<div className="_dsplFlx totals" >
							<div className="code tr_bar_70 fntW600 gSansFont"  style={{color: "var(--hrm_palette-inverse-background-b)"}}>
								{"Total:"} 
							</div>
							<div className="name tr_bar_30  gSansFont fntW600"  style={{color: "var(--hrm_palette-inverse-background-b)"}}>
								${((item?.tax + item?.sales )*1)?.toFixed(2)} 
							</div>	
						</div>
						<div className="_dsplFlx totals" >
							<div className="code tr_bar_70 gSansFont" >
								{"Costo:"} 
							</div>
							<div className="name tr_bar_30 gSansFont" >
								${ (item?.cost *-1 ).toFixed(2)} 
							</div>	
						</div>
						<div className="_dsplFlx totals" >
							<div className="code tr_bar_70 gSansFont" >
								{"Almacenaje:"} 
							</div>
							<div className="name tr_bar_30 gSansFont" >
								${ (item?.estimated_monthly_storage_fee*-1).toFixed(2)} 
							</div>	
						</div>
						<div className="_dsplFlx totals" >
							<div className="code tr_bar_70 fntW600 gSansFont"  style={{color: "var(--hrm_palette-inverse-background-b)"}}>
								{result>=0?"Ganancia:":"Perdida:"} 
							</div>
							<div className="name tr_bar_30  gSansFont fntW600 "  style={{color: result>=0 ? "#3fb950": "rgb(198, 40, 40)"}}>
								${( result  *1)?.toFixed(2)} 
							</div>	
						</div>
					</div>
				</div>
			</div>
			
		</div>
	);
};

export default ViewInvoice;









const ListingProducts  = ({ element, idKey, close }) => {
	
	
	return (
		<div className="_dsplFlx hdr_bar">
			<div className="tr_bar_25 gSansFont" style={{textAlign:"left", paddingLeft: 14}}>
				{element?.["amazon-order-id"]}
			</div>
			<div className="tr_bar_10 numbAlign gSansFont">
				{parseDateMMDDYYYY(new Date(element?.purchase_date).getTime())}
			</div>
			<div className="flexSpace"/>
			<div className="tr_bar_15 numbAlign gSansFont">
				{element?.item_status}
			</div>
			<div className="tr_bar_10 numbAlign gSansFont">
				${(element?.item_price*1)?.toFixed(2)}
			</div>
			<div className="tr_bar_10 numbAlign gSansFont">
				{(element?.quantity*1)?.toFixed(2)}
			</div>
			
		</div>
	)

}


const ListingWarehouse  = ({ element, idKey, close }) => {
	
	
	return (
		<div className="_dsplFlx hdr_bar">
			<div className="tr_bar_20 gSansFont" style={{textAlign:"left", paddingLeft: 14}}>
				{idKey}
			</div>
			<div className="tr_bar_15 numbAlign gSansFont">
				
			</div>
			<div className="tr_bar_15 numbAlign gSansFont">
				${(element?.shipped*1)?.toFixed(2)}
			</div>
			<div className="tr_bar_15 numbAlign gSansFont">
				{(element?.transfer*1)?.toFixed(2)}
			</div>
			<div className="tr_bar_15 numbAlign gSansFont">
				${(element?.receipts*1)?.toFixed(2)}
			</div>
			<div className="tr_bar_15 numbAlign gSansFont">
				{(element?.lost*1)?.toFixed(2)}
			</div>
			<div className="tr_bar_15 numbAlign gSansFont">
				{(element?.found*1)?.toFixed(2)}
			</div>
			
		</div>
	)

}

